import {setupSocialImport} from './social-import-ui.js';
import {safeUrl} from './social-import.js';
import {HISTORY} from './history.js';
import {today,ageAt,ranked,validateProfile} from './engine.js';
const $=s=>document.querySelector(s),key='cisheng-v1';let profile=null,demo=false,tab='all',pendingConfirm=null,toastTimer;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{const stored=JSON.parse(localStorage.getItem(key));if(validateProfile(stored))profile=stored;}catch{}
const personal=()=>profile?.memories||[];
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function persist(){if(demo)return;try{localStorage.setItem(key,JSON.stringify(profile));}catch{toast('浏览器无法保存，请立即导出备份，避免刷新后丢失。');}}
function scrollTo(id){$(id).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}
function info(title,html){$('#info-title').textContent=title;$('#info-content').innerHTML=html;$('#info-dialog').showModal();}
function confirmAction(title,text,action){$('#confirm-title').textContent=title;$('#confirm-text').textContent=text;pendingConfirm=action;$('#confirm-dialog').showModal();}
$('#confirm-action').onclick=()=>{$('#confirm-dialog').close();pendingConfirm?.();pendingConfirm=null;};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).close());
$('#birth').max=today();$('#memory-date').max=today();
$('#begin').onclick=()=>{if(profile){scrollTo('#workspace');return;}scrollTo('#onboarding');$('#birth').focus({preventScroll:true});};
$('#nav-timeline').onclick=()=>scrollTo(profile?'#workspace':'#onboarding');
$('#birth-form').onsubmit=e=>{e.preventDefault();const birth=$('#birth').value;const candidate={birth,name:$('#name').value.trim()||'我',memories:profile&&!demo?personal():[]};if(!validateProfile(candidate)){toast('请检查生日；生日不能晚于已有记忆，也不能是未来日期。');return;}profile=candidate;demo=false;persist();render();scrollTo('#workspace');toast('你的时间轴已经开启。');};
$('#demo').onclick=()=>{demo=true;profile={name:'林一',birth:'1990-06-15',memories:[{id:'demo1',date:'2008-09-01',title:'第一次离开家，去北京读大学',category:'升学',place:'北京 中国',note:'拖着一个大箱子走出车站。对这座刚办过奥运会的城市，既好奇，又有点紧张。'},{id:'demo2',date:'2015-07-06',title:'拿到第一份工作的工牌',category:'工作',place:'上海 中国',note:'从学生变成职场新人，在一家互联网公司开启新的生活。'},{id:'demo3',date:'2020-03-16',title:'把客厅变成了办公室',category:'工作',place:'上海 中国',note:'第一次长时间远程工作。开始认真做饭，也开始更频繁地给家里打电话。'}]};tab='all';render();scrollTo('#workspace');};
$('#exit-demo').onclick=()=>{profile=null;demo=false;try{const p=JSON.parse(localStorage.getItem(key));if(validateProfile(p))profile=p;}catch{}render();scrollTo(profile?'#workspace':'#onboarding');};
$('#edit-birth').onclick=()=>{$('#onboarding').hidden=false;$('#birth').value=profile.birth;$('#name').value=profile.name;scrollTo('#onboarding');};
function openMemory(id){if(!profile)return;const m=personal().find(m=>m.id===id);$('#memory-form').reset();$('#memory-id').value=m?.id||'';$('#memory-dialog-title').textContent=m?'编辑这段经历':'记下一段经历';$('#memory-date').min=profile.birth;$('#memory-date').value=m?.date||today();for(const field of ['title','category','place','note'])if(m)$('#memory-'+field).value=m[field];$('#memory-dialog').showModal();}
$('#add').onclick=()=>openMemory();
$('#memory-form').onsubmit=e=>{e.preventDefault();const id=$('#memory-id').value||crypto.randomUUID();const original=personal().find(m=>m.id===id);const m={...(original?.origin?{origin:original.origin}:{}),id,date:$('#memory-date').value,title:$('#memory-title').value.trim(),category:$('#memory-category').value,place:$('#memory-place').value.trim(),note:$('#memory-note').value.trim()};const memories=[...personal().filter(x=>x.id!==id),m];if(!validateProfile({...profile,memories})){toast('请填写有效的标题和日期，日期应在出生日至今天之间。');return;}profile.memories=memories;persist();$('#memory-dialog').close();render();toast(demo?'示例已更新；不会覆盖你的个人记录。':'已保存，相关历史也更新了。');};
function render(){const has=!!profile;$('#onboarding').hidden=has;$('#workspace').hidden=!has;$('#export').hidden=!has;if(!has)return;$('#demo-banner').hidden=!demo;$('#profile-label').textContent=demo?'一份虚构的示例人生':'你的个人时间档案';$('#timeline-title').textContent=profile.name==='我'?'我与时代':profile.name+'与时代';$('#profile-summary').textContent=`始于 ${profile.birth.replaceAll('-',' · ')} · 已与世界同行 ${ageAt(profile.birth,today())} 年`;$('#profile-name').textContent=profile.name;$('#birth-label').textContent=profile.birth+' 出生';$('#memory-count').textContent=personal().length;const history=ranked(profile.birth,personal());$('#history-count').textContent=history.length;document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-pressed',String(b.dataset.tab===tab));});const filter=$('#filter').value;$('#filter').disabled=tab==='mine';let events=history.filter(h=>filter==='all'||h.category===filter).map(h=>({...h,kind:'world'}));if(tab==='mine')events=[];if(tab==='related')events=events.filter(h=>h.links.length);if(tab!=='related')events.push(...personal().map(m=>({...m,kind:'personal'})),{kind:'birth',date:profile.birth,title:'你好，世界。',note:'你的故事，从这一天开始。'});events.sort((a,b)=>a.date.localeCompare(b.date)||(a.kind==='world'?1:-1));let html='';if(tab==='related'){html='<p class="form-note" style="margin-bottom:22px">按日期呈现匹配结果。时间接近、主题或地点相符均可形成线索；并不证明历史事件影响了你。</p>';if(!events.length)html+='<div class="empty"><h3>你的记忆，是连接的起点。</h3><p>补充一段经历，或切换主题，寻找与它相关的历史。</p><button class="primary" data-add>记下一段经历</button></div>';}
if(!personal().length&&tab!=='related')html+='<div class="empty"><h3>历史已经在这里，等你落笔。</h3><p>从一次升学、搬家或工作开始，让这条时间轴真正属于你。</p><button class="primary" data-add>添加第一段记忆</button></div>';
if(!history.length)html+='<p class="form-note" style="margin-bottom:20px">当前历史库暂无你出生后的条目。你仍可记录自己的经历；历史库将逐步补充。</p>';
const groups=new Map();events.forEach(e=>{const year=e.date.slice(0,4);if(!groups.has(year))groups.set(year,[]);groups.get(year).push(e);});for(const [year,items]of groups){html+=`<div class="year-block"><div class="year-label">${year}</div><div class="year-cards">${items.map(card).join('')}</div></div>`;}$('#timeline').innerHTML=html;}
function card(e){const isWorld=e.kind==='world';return `<article class="card ${isWorld?'world':'personal'}"><div class="card-meta"><span class="type">${isWorld?'时代历史':e.kind==='birth'?'生命起点':'个人记忆'}</span><span>${esc(e.date.slice(5).replace('-',' / '))}</span><span>${ageAt(profile.birth,e.date)} 岁</span><span>${esc(e.category||'出生')}</span></div><h3>${esc(e.title)}</h3><p>${esc(isWorld?e.text:e.note)}</p>${!isWorld&&e.place?`<p>地点 · ${esc(e.place)}</p>`:''}${!isWorld&&e.origin?`<div class="origin-label">导入自 ${esc(e.origin.platform)}${safeUrl(e.origin.url)?` · <a href="${esc(safeUrl(e.origin.url))}" target="_blank" rel="noopener noreferrer">查看原帖</a>`:''}</div>`:''}${isWorld&&e.links.length?`<div class="connection">✦ <strong>与你的「${esc(e.links[0].memory.title)}」相连</strong><br>${esc(e.links[0].reasons.join(' · '))}${e.links.length>1?` · 另关联 ${e.links.length-1} 段记忆`:''}</div>`:''}<div class="card-actions">${isWorld?`<a href="${e.url}" target="_blank" rel="noopener noreferrer">来源：${esc(e.source)}</a>${e.links.length?`<button data-reasons="${e.date}">查看全部关联</button>`:''}`:e.kind==='birth'?'':`<button data-edit="${esc(e.id)}">编辑</button><button data-delete="${esc(e.id)}">删除</button>`}</div></article>`;}
$('#timeline').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-add'))openMemory();if(b.dataset.edit)openMemory(b.dataset.edit);if(b.dataset.delete)confirmAction('删除这段记忆？','删除后，这段记忆形成的历史关联也会重新计算。',()=>{profile.memories=personal().filter(m=>m.id!==b.dataset.delete);persist();render();toast('记忆已删除。');});if(b.dataset.reasons){const h=ranked(profile.birth,personal()).find(h=>h.date===b.dataset.reasons);info('为什么与你相关',`<p>${esc(h.title)}</p><ul>${h.links.map(l=>`<li><strong>${esc(l.memory.title)}</strong><br>${esc(l.reasons.join('；'))}</li>`).join('')}</ul><p>这些是共同背景线索，并不意味着该历史事件直接改变了你的人生。</p>`);}};
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});$('#filter').onchange=render;
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,...profile},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`cisheng-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(demo?'示例故事已导出。':'备份已导出，请妥善保管。');};
$('#import').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>5000000){toast('文件过大，请选择小于 5 MB 的此生备份。');return;}try{const p=JSON.parse(await file.text());if(!validateProfile(p)||new Set(p.memories.map(m=>m.id)).size!==p.memories.length)throw Error();confirmAction('用备份替换当前记录？',`即将导入 ${p.memories.length} 段记忆。建议先导出当前记录。`,()=>{profile={name:p.name,birth:p.birth,memories:p.memories};demo=false;persist();render();toast('备份导入成功。');});}catch{toast('无法导入：请使用有效的此生 JSON 备份。');}};
$('#reset').onclick=()=>confirmAction('清除本机的个人记录？','清除后无法撤销，建议先导出备份。',()=>{if(!demo){try{localStorage.removeItem(key);}catch{toast('浏览器未允许清除，请通过浏览器设置删除网站数据。');return;}}profile=null;demo=false;render();scrollTo('#onboarding');toast('当前记录已清除。');});
$('#about').onclick=()=>info('每一个人，都在历史之中。','<p>此生是一份会生长的个人传记：从生日建立时间坐标，再用一段段真实记忆，让时代有了你的视角。</p><p>你可以记录、编辑和删除人生经历，也可以导入社交动态 JSON / CSV / X 归档，预览确认后合并到时间轴。支持查看历史关联和 JSON 备份，无需登录。</p><h3>关于隐私</h3><p>个人记录只保存在当前浏览器的本地存储中，不上传到服务器。换设备、清除网站数据或使用无痕模式可能丢失记录，请定期导出。公开链接不会分享你的个人传记。</p><h3>当前版本</h3><p>使用 12 条带来源的精选历史条目，覆盖 1945—2024 年的部分事件，不是完整历史数据库。匹配依据为时间、地点、主题规则，未接入生成式 AI 或实时新闻。</p><button class="outline" id="info-import">导入我的备份</button> <button class="outline" id="info-edit">修改个人信息</button> <button class="outline" id="info-reset">清除记录</button>');
$('#info-content').onclick=e=>{if(e.target.id==='info-import'){$('#info-dialog').close();$('#import-file').click();}if(e.target.id==='info-edit'){$('#info-dialog').close();if(profile)$('#edit-birth').click();else scrollTo('#onboarding');}if(e.target.id==='info-reset'){$('#info-dialog').close();if(profile)$('#reset').click();else toast('还没有个人记录。');}};
$('#sources').onclick=()=>info('历史来源与关联说明',`<p>以下为首版精选事件，日期和事实来自对应机构。中文简介为独立概述。历史库有限，生日当天没有事件时不会编造“同日大事”。</p><p>关联规则：经历前后一年 +5 分，前后三年 +3 分；匹配主题 +3 分，地点 +4 分。单段经历得分至少 3 分时展示关联。时间轴只呈现出生后至今的历史。</p><ul>${HISTORY.map(h=>`<li>${h.date} · ${h.title}<br><a href="${h.url}" target="_blank" rel="noopener noreferrer">${h.source}</a></li>`).join('')}</ul>`);
setupSocialImport({
  getProfile:()=>profile, isDemo:()=>demo, esc, toast,
  commit(memories){
    if(!profile || demo) return {ok:false,message:'请先建立自己的生日档案。'};
    const candidate={...profile,memories:[...personal(),...memories]};
    if(!validateProfile(candidate)) return {ok:false,message:'条目不符合日期或文字限制，或总数超过 1,000 条。'};
    // Persist atomically before updating the visible profile. Quota errors keep the preview intact.
    try{localStorage.setItem(key,JSON.stringify(candidate));}
    catch{return {ok:false,message:'浏览器存储空间不足或不允许保存。本次未导入，请减少条目，或先导出已有记录。'};}
    profile=candidate;tab='all';$('#filter').value='all';render();
    return {ok:true};
  }
});
render();
